        volumes = [
          "local/nginx.conf:/usr/local/openresty/nginx/conf/nginx.conf:ro",
          "local/ban-rules.conf:/usr/local/openresty/nginx/conf/ban-rules.conf:ro",
          "local/ban-check.lua:/usr/local/openresty/nginx/conf/ban-check.lua:ro",
        ]
